1	#!/usr/bin/env node
2	// ng-facts — structural facts and a codemod for an Angular workspace, computed with the Angular compiler (no LLM).
3	//   ng-facts usages <selector|Class>[.<input>] [--root <dir>]
4	//   ng-facts rename-input <Class>.<old> <new> [--negate] [--write] [--root <dir>]
5	//   ng-facts migrate <spec.json | '{…}'> [--write] [--root <dir>]   (an API migration described as data, applied mechanically)
6	//   ng-facts where <selector|Class> [--root <dir>]     (who renders it, directly and through others, and on which routes)
7	//   ng-facts unrouted [--root <dir>]                   (components no route can show)
8	//   ng-facts check [--root <dir>]                      (the compiler's verdict in a few lines)
9	import { spawnSync } from "node:child_process";
10	import { existsSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
11	import path from "node:path";
12	import { fileURLToPath } from "node:url";
13	import * as ng from "@angular/compiler";
14	import ts from "typescript";
15	
16	const DECORATORS = new Set([ "Component", "Directive" ]);
17	const INPUT_FACTORIES = new Set([ "input", "model" ]);
18	
19	function listSources(dir) {
20	    return readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
21	        const full = path.join(dir, entry.name);
22	        if (entry.isDirectory()) return entry.name === "node_modules" || entry.name.startsWith(".") ? [] : listSources(full);
23	        return entry.name.endsWith(".ts") && !entry.name.endsWith(".spec.ts") && !entry.name.endsWith(".d.ts") ? [ full ] : [];
24	    });
25	}
26	
27	function decoratorCall(node) {
28	    for (const decorator of ts.getDecorators(node) ?? []) {
29	        const call = decorator.expression;
30	        if (ts.isCallExpression(call) && ts.isIdentifier(call.expression) && DECORATORS.has(call.expression.text)) return call;
31	    }
32	    return undefined;
33	}
34	
35	function inputOf(member) {
36	    if (!ts.isPropertyDeclaration(member) || !member.initializer || !ts.isCallExpression(member.initializer)) return undefined;
37	    const callee = member.initializer.expression;
38	    const factory = ts.isIdentifier(callee) ? callee.text : ts.isPropertyAccessExpression(callee) && ts.isIdentifier(callee.expression) ? callee.expression.text : "";
39	    if (!INPUT_FACTORIES.has(factory)) return undefined;
40	    const options = member.initializer.arguments.find(argument => ts.isObjectLiteralExpression(argument));
41	    const alias = options?.properties.find(property => property.name?.getText() === "alias")?.initializer;
42	    const name = member.name.getText();
43	    return { name, bindingName: alias && ts.isStringLiteral(alias) ? alias.text : name, member };
44	}
45	
46	function templateSource(file, sourceFile, property) {
47	    const value = property.initializer;
48	    if (property.name.getText() === "template" && (ts.isNoSubstitutionTemplateLiteral(value) || ts.isStringLiteral(value))) {
49	        return { file, offset: value.getStart(sourceFile) + 1, text: value.getText(sourceFile).slice(1, -1), inline: true };
50	    }
51	    if (property.name.getText() === "templateUrl" && ts.isStringLiteral(value)) {
52	        const templateFile = path.resolve(path.dirname(file), value.text);
53	        return { file: templateFile, offset: 0, text: readFileSync(templateFile, "utf8"), inline: false };
54	    }
55	    return undefined;
56	}
57	
58	/** Every @Component/@Directive with its selector, signal inputs and parsed template. */
59	export function loadWorkspace(root) {
60	    const declarations = [];
