495	/** One writer at a time: two migrations interleaving their edits corrupt the files they share. */
496	function withWriteLock(root, action) {
497	    const lock = path.join(root, ".ng-facts.lock");
498	    if (existsSync(lock)) {
499	        const owner = Number(readFileSync(lock, "utf8"));
500	        let alive = Number.isInteger(owner);
501	        try {
502	            if (alive) process.kill(owner, 0);
503	        } catch {
504	            alive = false;
505	        }
506	        if (alive) throw new Error(`another ng-facts write is running in this workspace (pid ${owner}) — wait for it, do not start a second one`);
507	    }
508	    writeFileSync(lock, String(process.pid));
509	    try {
510	        return action();
511	    } finally {
512	        rmSync(lock, { force: true });
513	    }
514	}
515	
516	/** Runs ngc on the workspace and answers in a few lines: the raw output of a broken workspace runs to hundreds of kilobytes. */
517	function compilerVerdict(root) {
518	    // node starts the compiler's own script: node_modules/.bin/ngc is a shell script that Windows cannot start as a program
519	    const manifestPath = "node_modules/@angular/compiler-cli/package.json";
520	    let directory = root;
521	    while (!existsSync(path.join(directory, manifestPath)) && path.dirname(directory) !== directory) directory = path.dirname(directory);
522	    if (!existsSync(path.join(directory, manifestPath))) return "ngc: not found in node_modules — run it yourself";
523	    const ngc = path.resolve(directory, path.dirname(manifestPath), JSON.parse(readFileSync(path.join(directory, manifestPath), "utf8")).bin.ngc);
524	    const run = spawnSync(process.execPath, [ ngc, "-p", path.join(root, "tsconfig.json") ], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });
525	    const output = `${run.stdout ?? ""}${run.stderr ?? ""}`.replace(/\x1b\[[0-9;]*m/g, "");
526	    const errors = [ ...output.matchAll(/^(.+?):(\d+):(\d+) - error ((?:NG|TS)\d+): (.*)$/gm) ].map(([ , file, line, column, code, message ]) => ({ file, line, column, code, message }));
527	    if (!errors.length) return run.status === 0 ? "ngc: 0 errors" : `ngc: failed without a parsable error — ${output.trim().split("\n")[0] ?? ""}`;
528	    const byCode = [ ...Map.groupBy(errors, error => error.code) ].map(([ code, list ]) => `${code} ×${list.length}`).join(", ");
529	    const kinds = [ ...Map.groupBy(errors, error => `${error.code} ${error.message}`).values() ];
530	    const shown = kinds.slice(0, 5).map(([ first, ...rest ]) => `  ${first.file}:${first.line}:${first.column} ${first.code} ${first.message}${rest.length ? ` (+${rest.length} more like it)` : ""}`);
531	    return [ `ngc: ${errors.length} errors in ${new Set(errors.map(error => error.file)).size} files — ${byCode}`, ...shown, ...(kinds.length > 5 ? [ `  … and ${kinds.length - 5} more kinds of error` ] : []) ].join("\n");
532	}
533	
534	function parseArgs(argv) {
535	    const flags = { root: "fixture", negate: false, write: false, all: false };
536	    const positional = [];
537	    for (let index = 0; index < argv.length; index++) {
538	        if (argv[index] === "--root") flags.root = argv[++index];
539	        else if (argv[index] === "--negate") flags.negate = true;
540	        else if (argv[index] === "--write") flags.write = true;
541	        else if (argv[index] === "--all") flags.all = true;
542	        else positional.push(argv[index]);
543	    }
544	    return { flags, positional };
545	}
546	
547	function main() {
548	    const [ command, ...rest ] = process.argv.slice(2);
549	    const { flags, positional } = parseArgs(rest);
550	    if (command === "migrate" && (!positional[0] || positional[0] === "--help")) {
551	        console.log(MIGRATION_SPEC_HELP);
552	        return;
553	    }
554	    const started = performance.now();
555	    const workspace = loadWorkspace(path.resolve(flags.root));
556	    const elapsed = () => `${Math.round(performance.now() - started)} ms`;
557	
558	    if (command === "usages") {
559	        const [ target, inputName ] = positional[0].split(".");
560	        const owner = findDeclaration(workspace, target);
561	        const { uses, decoys } = findUsages(workspace, owner, inputName);
562	        const files = new Set(uses.map(entry => entry.template.file));
563	        console.log(`${owner.className} <${owner.selector}>${inputName ? `.${inputName}` : ""}: ${uses.length} uses in ${files.size} files (${elapsed()}, ${workspace.declarations.length} declarations)`);
564	        const shown = flags.all ? uses : uses.slice(0, 8);
565	        for (const entry of shown) console.log(`  ${describe(workspace, entry)}`);
566	        if (uses.length > shown.length) console.log(`  … +${uses.length - shown.length} more (--all lists every use)`);
567	        if (inputName) {
568	            const values = Map.groupBy(uses, entry => String(entry.binding.value?.source ?? entry.binding.value).trim());
569	            console.log(`Values: ${[ ...values ].map(([ value, list ]) => `${value} ×${list.length}`).join(", ")}`);
570	            console.log(`Same name on other elements: ${decoys.length} bindings on ${[ ...new Set(decoys.map(entry => `<${entry.element.name}>`)) ].join(", ") || "—"} — these elements do not match the selector of ${owner.className}; whether their component extends it is not followed`);
571	            console.log(`→ rename everywhere: ng-facts rename-input ${owner.className}.${inputName} <newName> [--negate] --write`);
572	        }
573	        return;
574	    }
575	
576	    if (command === "rename-input") {
577	        const [ target, oldName ] = positional[0].split(".");
578	        const owner = findDeclaration(workspace, target);
579	        const result = renameInput(workspace, owner, oldName, positional[1], flags);
580	        console.log(`rename-input ${owner.className}.${oldName} → ${positional[1]}${flags.negate ? " (negated)" : ""}: ${result.edits.length} edits in ${result.files.size} files, ${result.uses} bindings, ${result.decisions.length} need a decision — ${flags.write ? "written" : "dry run, add --write"} (${elapsed()})`);
581	        for (const decision of flags.all ? result.decisions : result.decisions.slice(0, 20)) console.log(`  needs a decision: ${decision}`);
582	        if (result.decisions.length > 20 && !flags.all) console.log(`  … +${result.decisions.length - 20} more (--all lists every one)`);
583	        return;
584	    }
585	
586	    if (command === "where") {
587	        const owner = findDeclaration(workspace, positional[0]);
588	        const graph = renderGraph(workspace);
589	        const { routes } = routesOf(workspace.root);
590	        const ancestors = reachable([ owner ], graph.parents);
591	        const names = new Set([ ...ancestors ].map(declaration => declaration.className));
592	        const showing = routes.filter(route => route.components.some(name => names.has(name)));
593	        const routed = new Set(routes.flatMap(route => route.components));
594	        const deadEnds = [ ...ancestors ].filter(declaration => declaration !== owner && !graph.parents.get(declaration).size && !routed.has(declaration.className));
595	        const direct = [ ...graph.parents.get(owner) ];
596	        console.log(`${owner.className} <${owner.selector}>: rendered directly by ${direct.length} components, through others by ${ancestors.size - 1 - direct.length} more; can be shown on ${showing.length} of ${routes.length} routes (${elapsed()})`);
597	        console.log(`Rendered directly by: ${direct.map(declaration => declaration.className).join(", ") || "—"}`);
598	        console.log(`Routes that can show it (${showing.length}): ${showing.map(route => route.path).join(", ") || "—"}`);
599	        if (deadEnds.length) console.log(`Also rendered by components no route leads to: ${deadEnds.map(declaration => declaration.className).join(", ")}`);
600	        return;
601	    }
602	
603	    if (command === "unrouted") {
604	        const graph = renderGraph(workspace);
605	        const { routes, bootstrapped } = routesOf(workspace.root);
606	        const entry = new Set([ ...routes.flatMap(route => route.components), ...(bootstrapped ? [ bootstrapped ] : []) ]);
607	        const onScreen = reachable(workspace.declarations.filter(declaration => entry.has(declaration.className)), graph.children);
608	        const unrouted = workspace.declarations.filter(declaration => !onScreen.has(declaration));
609	        console.log(`${unrouted.length} of ${workspace.declarations.length} components can never be shown: no route mounts them and nothing on screen renders them (${routes.length} routes, ${elapsed()})`);
610	        for (const declaration of unrouted) console.log(`  ${declaration.className}  ${path.relative(workspace.root, declaration.file)}`);
611	        return;
612	    }
613	
614	    if (command === "check") {
615	        const verdict = compilerVerdict(workspace.root);
616	        console.log(verdict);
617	        // exit code 1 when the compiler found an error: `check && next step` must not go on then
618	        if (verdict !== "ngc: 0 errors") process.exitCode = 1;
619	        return;
620	    }
621	
622	    if (command === "migrate") {
623	        const inline = positional[0].trim().startsWith("{");
624	        const spec = JSON.parse(inline ? positional[0] : readFileSync(path.resolve(positional[0]), "utf8"));
625	        const result = flags.write ? withWriteLock(workspace.root, () => migrate(workspace, spec, flags)) : migrate(workspace, spec, flags);
626	        console.log(`migrate ${spec.component}: ${result.elements} elements, ${result.edits.length} edits in ${result.files.size} files, ${result.imports} components get a new import, ${result.decisions.length} need a decision — ${flags.write ? "written" : "dry run, add --write"} (${elapsed()})`);
627	        for (const decision of result.decisions.slice(0, 20)) console.log(`  needs a decision: ${decision}`);
628	        if (flags.write) {
629	            const left = migrate(loadWorkspace(workspace.root), spec).edits.length;
630	            console.log(left ? `verify: ${left} edits would still apply — inspect before running it again` : "verify: nothing left to migrate");
631	            console.log(compilerVerdict(workspace.root));
632	        }
633	        return;
634	    }
635	
636	    console.log("usage: ng-facts usages <selector|Class>[.<input>] [--all] | where <selector|Class> | unrouted | check | rename-input <Class>.<old> <new> [--negate] [--write] | migrate <spec.json> [--write] | migrate --help   [--root <dir>]");
637	}
638	
639	if (process.argv[1] === fileURLToPath(import.meta.url)) {
640	    try {
641	        main();
642	    } catch (error) {
643	        console.error(error.message);
644	        process.exit(1);
645	    }
646	}
