import { loadWorkspace } from "../tools/ng-facts.mjs";
import * as ng from "@angular/compiler";
import path from "node:path";

const ws = loadWorkspace(path.resolve("."));
const NAME = process.argv[2] ?? "disableTooltip";

class EC extends ng.TmplAstRecursiveVisitor {
    elements = [];
    visitElement(e) { this.elements.push(e); super.visitElement(e); }
}

const byElement = new Map();
for (const d of ws.declarations) {
    if (!d.template) continue;
    const c = new EC();
    ng.tmplAstVisitAll(c, d.template.nodes);
    for (const el of c.elements) {
        for (const b of [ ...el.inputs, ...el.attributes ]) {
            if (b.name !== NAME) continue;
            const sel = new ng.CssSelector();
            sel.setElement(el.name);
            for (const a of el.attributes) sel.addAttribute(a.name, a.value);
            for (const i of el.inputs) if (i.type === ng.BindingType.Property) sel.addAttribute(i.name, "");
            const matched = [];
            ws.matcher.match(sel, (_s, decl) => matched.push(decl.className));
            const key = `<${el.name}> -> ${matched.join(",") || "NONE"}`;
            byElement.set(key, (byElement.get(key) ?? 0) + 1);
        }
    }
}
console.log("=== bindings named " + NAME + " by element ===");
for (const [ k, v ] of [ ...byElement ].sort()) console.log(`  ${v}\t${k}`);

// declarations that declare an input with this name
console.log("=== declarations declaring it ===");
for (const d of ws.declarations) if (d.inputs.some(i => i.name === NAME)) console.log(`  ${d.className}  <${d.selector}>  ${path.relative(ws.root, d.file)}`);
console.log("=== all selectors of Pill family ===");
for (const d of ws.declarations) if (/Pill|Card|Hint/.test(d.className)) console.log(`  ${d.className}  <${d.selector}>`);

