// Renames reads/bindings of PillComponent.disableTooltip that `ng-facts rename-input` does not cover:
// bindings on subclass selectors, expression reads in templates and TypeScript, setInput strings, CSS selectors.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import * as ng from "@angular/compiler";
import ts from "typescript";
import { loadWorkspace } from "../tools/ng-facts.mjs";

const OLD = "disableTooltip";
const NEW = "hideHint";
const OWNER = "PillComponent";                                   // the class that declares the input
const FAMILY = new Set([ "PillComponent", "FancyPillComponent", "StatusPillComponent" ]);
const WRITE = process.argv.includes("--write");
const ROOT = path.resolve(".");

const edits = [];
const report = [];
const edit = (file, start, end, why) => {
    edits.push({ file, start, end, text: NEW });
    report.push({ file, start, why });
};

const texts = new Map();
const textOf = file => {
    if (!texts.has(file)) texts.set(file, readFileSync(file, "utf8"));
    return texts.get(file);
};
const lineOf = (text, offset) => {
    let line = 1;
    for (let i = 0; i < offset; i++) if (text.charCodeAt(i) === 10) line++;
    return line;
};

// ---------- templates ----------
const ws = loadWorkspace(ROOT);

class Elements extends ng.TmplAstRecursiveVisitor {
    elements = [];
    visitElement(e) { this.elements.push(e); super.visitElement(e); }
}
class Expressions extends ng.TmplAstRecursiveVisitor {
    expressions = [];
    visitBoundAttribute(a) { this.expressions.push(a.value); }
    visitBoundText(t) { this.expressions.push(t.value); }
    visitBoundEvent(e) { this.expressions.push(e.handler); }
    visitIfBlockBranch(b) { if (b.expression) this.expressions.push(b.expression); super.visitIfBlockBranch(b); }
    visitForLoopBlock(b) { this.expressions.push(b.expression); super.visitForLoopBlock(b); }
    visitSwitchBlock(b) { this.expressions.push(b.expression); super.visitSwitchBlock(b); }
    visitSwitchBlockCase(c) { if (c.expression) this.expressions.push(c.expression); super.visitSwitchBlockCase(c); }
}
function walk(ast, visit, parent) {
    if (!(ast instanceof ng.AST)) return;
    visit(ast, parent);
    for (const value of Object.values(ast)) {
        if (value instanceof ng.AST) walk(value, visit, ast);
        else if (Array.isArray(value)) for (const item of value) walk(item, visit, ast);
    }
}
const classesOf = element => {
    const selector = new ng.CssSelector();
    selector.setElement(element.name);
    for (const a of element.attributes) selector.addAttribute(a.name, a.value);
    for (const i of element.inputs) if (i.type === ng.BindingType.Property) selector.addAttribute(i.name, "");
    const matched = [];
    ws.matcher.match(selector, (_s, declaration) => matched.push(declaration.className));
    return matched;
};

const seenTemplates = new Set();
for (const declaration of ws.declarations) {
    const template = declaration.template;
    if (!template) continue;
    const at = offset => template.offset + offset;
    const key = `${template.file}:${template.offset}`;
    if (seenTemplates.has(key)) continue;
    seenTemplates.add(key);

    const elementCollector = new Elements();
    ng.tmplAstVisitAll(elementCollector, template.nodes);

    // bindings of the input on an element of the family; <app-pill> itself is left to ng-facts
    const refTargets = new Map();
    for (const element of elementCollector.elements) {
        const classes = classesOf(element);
        for (const reference of element.references) refTargets.set(reference.name, classes);
        if (!classes.some(name => FAMILY.has(name)) || classes.includes(OWNER)) continue;
        for (const binding of [ ...element.inputs, ...element.attributes ]) {
            if (binding.name !== OLD) continue;
            edit(template.file, at(binding.keySpan.start.offset), at(binding.keySpan.end.offset), `binding on <${element.name}> (${classes.join(",")})`);
        }
    }

    // reads of the input inside the template
    const expressionCollector = new Expressions();
    ng.tmplAstVisitAll(expressionCollector, template.nodes);
    for (const expression of expressionCollector.expressions) {
        walk(expression, node => {
            if (!(node instanceof ng.PropertyRead) && !(node instanceof ng.SafePropertyRead)) return;
            if (node.name !== OLD) return;
            const receiver = node.receiver;
            if (receiver instanceof ng.ImplicitReceiver) {
                // the template's own component: only the family's own templates read the renamed input
                if (!FAMILY.has(declaration.className)) return;
                edit(template.file, at(node.nameSpan.start), at(node.nameSpan.end), `own template read in ${declaration.className}`);
                return;
            }
            const refName = (receiver instanceof ng.PropertyRead || receiver instanceof ng.SafePropertyRead) && receiver.receiver instanceof ng.ImplicitReceiver ? receiver.name : undefined;
            const classes = refName ? refTargets.get(refName) : undefined;
            if (!classes) return;                                 // not a template reference: nothing to decide here
            if (classes.some(name => FAMILY.has(name))) edit(template.file, at(node.nameSpan.start), at(node.nameSpan.end), `read via #${refName} (${classes.join(",")}) in ${path.relative(ROOT, template.file)}`);
        });
    }
}

// ---------- TypeScript ----------
function sources(dir) {
    return readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) return entry.name === "node_modules" || entry.name.startsWith(".") ? [] : sources(full);
        return entry.name.endsWith(".ts") && !entry.name.endsWith(".d.ts") ? [ full ] : [];
    });
}
const config = ts.parseJsonConfigFileContent(JSON.parse(readFileSync(path.join(ROOT, "tsconfig.json"), "utf8")), ts.sys, ROOT);
const program = ts.createProgram(sources(path.join(ROOT, "src")), { ...config.options, noEmit: true });
const checker = program.getTypeChecker();

const declaringClassOf = symbol => {
    for (const declaration of symbol?.declarations ?? []) {
        const parent = declaration.parent;
        if (parent && ts.isClassDeclaration(parent) && parent.name) return parent.name.text;
    }
    return undefined;
};

for (const sourceFile of program.getSourceFiles()) {
    if (sourceFile.isDeclarationFile || !sourceFile.fileName.includes("/src/")) continue;
    const file = path.normalize(sourceFile.fileName);
    sourceFile.forEachChild(function visit(node) {
        // x.disableTooltip — rename when the property resolves to the input declared by PillComponent
        if ((ts.isPropertyAccessExpression(node) || ts.isElementAccessExpression(node)) && ts.isPropertyAccessExpression(node) && node.name.text === OLD) {
            const owner = declaringClassOf(checker.getSymbolAtLocation(node.name));
            if (owner === OWNER) edit(file, node.name.getStart(sourceFile), node.name.getEnd(), `TS read ${node.getText(sourceFile)} (declared by ${owner})`);
        }
        // setInput("disableTooltip", …) on a ComponentRef of the family
        if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression) && node.expression.name.text === "setInput") {
            const [ nameArgument ] = node.arguments;
            if (nameArgument && ts.isStringLiteralLike(nameArgument) && nameArgument.text === OLD) {
                const type = checker.getTypeAtLocation(node.expression.expression);
                const component = checker.getTypeArguments(type)?.[0] ?? type.aliasTypeArguments?.[0];
                const name = component ? checker.typeToString(component) : "?";
                if (FAMILY.has(name)) edit(file, nameArgument.getStart(sourceFile) + 1, nameArgument.getEnd() - 1, `setInput on ComponentRef<${name}>`);
                else report.push({ file, start: nameArgument.getStart(sourceFile), why: `SKIPPED setInput on ComponentRef<${name}>` });
            }
        }
        node.forEachChild(visit);
    });
}

// ---------- style sheets ----------
for (const file of [ path.join(ROOT, "src", "styles.css") ]) {
    const text = textOf(file);
    for (const match of text.matchAll(new RegExp(`(app-[a-z-]+)\\[${OLD}\\]`, "g"))) {
        const element = match[1];
        const owner = ws.declarations.find(declaration => declaration.selector === element)?.className;
        const start = match.index + element.length + 1;
        if (owner && FAMILY.has(owner)) edit(file, start, start + OLD.length, `CSS selector ${element}[${OLD}] (${owner})`);
        else report.push({ file, start, why: `SKIPPED CSS selector ${element}[${OLD}] (${owner ?? "unknown"})` });
    }
}

// ---------- apply ----------
const grouped = new Map();
for (const entry of report) {
    const line = `${path.relative(ROOT, entry.file)}:${lineOf(textOf(entry.file), entry.start)}`;
    const kind = entry.why.replace(/ in src.*$/, "").replace(/\(.*?\)/g, m => m);
    grouped.set(kind, [ ...(grouped.get(kind) ?? []), line ]);
}
for (const [ kind, lines ] of [ ...grouped ].sort()) console.log(`${String(lines.length).padStart(4)}  ${kind}\n        e.g. ${lines.slice(0, 3).join(", ")}`);
console.log(`${edits.length} edits in ${new Set(edits.map(e => e.file)).size} files — ${WRITE ? "written" : "dry run"}`);

if (WRITE) {
    for (const [ file, fileEdits ] of Map.groupBy(edits, entry => entry.file)) {
        let text = readFileSync(file, "utf8");
        for (const entry of fileEdits.sort((l, r) => r.start - l.start)) text = text.slice(0, entry.start) + entry.text + text.slice(entry.end);
        writeFileSync(file, text);
    }
}

